import functools
import redis
from flask import abort, request
from .config import REDIS_URL

_r = redis.Redis.from_url(REDIS_URL)

def limit(per_minute: int):
    def wrap(fn):
        @functools.wraps(fn)
        def inner(*a, **kw):
            key = f'rl:{request.remote_addr}:{fn.__name__}'
            n, _ = _r.pipeline().incr(key).expire(key, 60).execute()
            if n > per_minute:
                abort(429)
            return fn(*a, **kw)
        return inner
    return wrap
